inline std::string_view GetStageBgm(int stage) {
    switch (stage) {
        case 1: return stage1;
        case 2: return stage2;
        case 3: return stage3;
        case 4: return stage4.empty() ? stage1 : stage4;
        case 5: return stage5;
        case 6: return stage6;
        default: return stage1;
    }
}

inline std::string_view GetBossBgm(int stage) {
    switch (stage) {
        case 1: return boss1;
        case 2: return boss2;
        case 3: return boss3;
        case 4: return boss4;
        case 5: return boss5;
        case 6: return boss6;
        default: return boss1;
    }
}

inline std::string_view GetTitleBgm() { return title; }
inline std::string_view GetEndingBgm() { return ending; }

inline std::string_view GetByName(std::string_view name) {
    if (name == "title") return title;
    if (name == "ending") return ending;
    if (name == "stage1") return stage1;
    if (name == "stage2") return stage2;
    if (name == "stage3") return stage3;
    if (name == "stage4") return stage4;
    if (name == "stage5") return stage5;
    if (name == "stage6") return stage6;
    if (name == "boss1") return boss1;
    if (name == "boss2") return boss2;
    if (name == "boss3") return boss3;
    if (name == "boss4") return boss4;
    if (name == "boss5") return boss5;
    if (name == "boss6") return boss6;
    return {};
}

